// Chartolj! — English lesson translations, module 4 (Advanced Market Knowledge).
// Keys are LESSONS_DATA indices; quiz option order and correct answers are unchanged.
window.LESSONS_EN = Object.assign(window.LESSONS_EN || {}, {
"500": {"t": "Order Flow and the Game Behind the Book", "s": "What happens behind the candles: order book, spread, market maker", "cards": [
  {"t": "What is order flow?", "b": "<p><strong style=\"color:#A855F7\">Order flow</strong> is the continuous stream of buy and sell orders arriving in the market. Every candle you see is actually the result of thousands of individual orders (market orders and limit orders) — the candle only shows the END RESULT, not how it came about.</p>"},
  {"t": "Bid-ask spread", "b": "<p>The <strong style=\"color:#A855F7\">bid</strong> is the highest price someone wants to buy at, the <strong style=\"color:#A855F7\">ask</strong> is the lowest price someone wants to sell at. The difference between the two is the <strong style=\"color:#A855F7\">spread</strong> — one of the best measures of a market's liquidity: the narrower it is, the more liquid (easier to trade) the asset.</p>"},
  {"t": "The role of the market maker", "b": "<p>A <strong style=\"color:#A855F7\">market maker</strong> continuously quotes on both sides (buy and sell), making sure there is always someone to trade with. Their profit typically comes from the spread — many small gains, in large volume, not directional speculation.</p>"},
  {"t": "The stop-hunting phenomenon", "b": "<p>Many beginners place their stop-loss right next to round numbers (e.g. 100, 50000). Knowing this, larger players sometimes 'push' the price exactly to these levels (with a short, sharp swing) to knock out these stops before the move continues in the original direction. That's why it is worth placing your stop a little BEFORE or BEHIND the round level, not exactly on it.</p>"}],
 "qs": [
  {"q": "What does the term order flow mean?", "o": ["A given stock's dividend payment schedule", "The continuous stream of buy and sell orders arriving in the market", "A type of technical indicator similar to the RSI", "The official trading hours of an exchange"], "e": "Order flow is the continuous stream of actually arriving orders (buy/sell) — every candle is made up of this."},
  {"q": "What is the bid-ask spread?", "o": ["The difference between the day's highest and lowest price", "The difference between the best buy price and the best sell price", "A type of moving-average indicator", "A fixed percentage brokerage commission"], "e": "The spread is the difference between the best bid (buy offer) and the best ask (sell offer) — one of the main measures of liquidity."},
  {"q": "Where does a market maker's profit typically come from?", "o": ["Exclusively from long-term directional speculation", "From the spread, through a large volume of transactions", "From government subsidies", "From commissions taken from traders' losses"], "e": "A market maker typically profits from the bid-ask spread, not from directional speculation — they continuously quote on both sides."},
  {"q": "Why is it risky to place a stop-loss exactly next to a round number?", "o": ["Because brokers charge a higher commission there", "Because other traders' stops often concentrate there, which larger players sometimes exploit", "Because round numbers are banned on most exchanges", "Because the price always stops there and never breaks through"], "e": "Many traders' stops concentrate around round numbers — larger players sometimes exploit this with a short, sharp swing before the move continues."}
 ]},
"501": {"t": "Volume Analysis and Volume Profile", "s": "VWAP, Point of Control, and volume as a confirming signal", "cards": [
  {"t": "Volume as confirmation", "b": "<p>Price movement on its own can be misleading — <strong style=\"color:#A855F7\">volume</strong> (the quantity traded) shows whether REAL conviction stands behind the move. A breakout on high volume is far more reliable than the same breakout on low volume.</p>"},
  {"t": "VWAP — the Volume Weighted Average Price", "b": "<p><strong style=\"color:#A855F7\">VWAP</strong> (Volume Weighted Average Price) shows the average price at which the asset changed hands during the day, weighted by volume. Institutional traders often use it as a reference point: price above VWAP signals strength, price below VWAP signals weakness intraday.</p>"},
  {"t": "Volume Profile and the Point of Control", "b": "<p><strong style=\"color:#A855F7\">Volume Profile</strong> shows the traded quantity not over time but BY PRICE LEVEL. The <strong style=\"color:#A855F7\">Point of Control (POC)</strong> is the price level where the MOST trading took place — this often behaves as a strong support or resistance level in the future as well.</p>"},
  {"t": "Volume divergence", "b": "<p>If the price reaches a new high but volume DECREASES compared to the previous high, that can point to weakening conviction — fewer and fewer traders 'believe' the move. This can be an early warning sign of an approaching reversal, even before anything shows up on the price itself.</p>"}],
 "qs": [
  {"q": "Why is volume important when judging a breakout?", "o": ["Because volume determines brokerage fees", "Because a high-volume breakout is a far more reliable signal than a low-volume one", "Because volume always exactly matches the size of the price move", "Because the exchange automatically halts trading on low volume"], "e": "Volume shows the real conviction behind a move — a high-volume breakout is far more reliable than a weak, low-volume one."},
  {"q": "What does VWAP show?", "o": ["The weekly highest price", "The volume-weighted average price over the course of the day", "A long-term trendline", "The next day's expected opening price"], "e": "VWAP is the volume-weighted average price — a common reference point for institutional traders when judging intraday strength/weakness."},
  {"q": "What is the Point of Control (POC)?", "o": ["The official regulatory body of the exchange", "The price level where the most trading took place in a given period", "A mandatory stop-loss level required by the broker", "The average of the daily open and close"], "e": "The POC is the highest-volume price level of the Volume Profile — it often behaves as a strong support/resistance level later as well."},
  {"q": "What can it suggest if the price makes a new high but volume decreases?", "o": ["That the trend is guaranteed to continue", "Weakening conviction, which can be an early warning sign before a reversal", "That the exchange has detected a technical glitch", "Nothing — volume and price are always independent of each other"], "e": "A new high on decreasing volume (volume divergence) can point to weakening conviction — an early sign of an approaching reversal."}
 ]},
"502": {"t": "Intermarket Relationships", "s": "How the dollar, gold, bonds, and the stock market connect to each other", "cards": [
  {"t": "The dollar index (DXY) and gold", "b": "<p>Gold is an asset priced in dollars, so it typically moves in <strong style=\"color:#A855F7\">inverse (negative) correlation</strong> with the dollar index (DXY): if the dollar strengthens, that makes gold more expensive in other currencies, which can reduce demand — and vice versa.</p>"},
  {"t": "Bond yields and the stock market", "b": "<p>When government bond yields RISE, the safe, risk-free yield becomes more attractive compared to risky stocks — this often puts PRESSURE on the stock market, especially stocks with high growth expectations (tech).</p>"},
  {"t": "Risk-on / risk-off cycles", "b": "<p>Markets often move together along a shared 'mood': in a <strong style=\"color:#A855F7\">risk-on</strong> period (optimism) stocks and cryptocurrencies rise while the dollar and government bonds weaken; in a <strong style=\"color:#A855F7\">risk-off</strong> period (fear) the opposite happens — capital flees into 'safe havens' (dollar, gold, government bonds).</p>"},
  {"t": "Correlation is not causation", "b": "<p>An important caution: two assets moving together (correlation) does not mean that one CAUSES the other, and correlations CHANGE over time, sometimes even reversing. Intermarket analysis is a supplementary tool for decision-making, not a mechanical trading rule sufficient on its own.</p>"}],
 "qs": [
  {"q": "What is the typical relationship between the dollar index (DXY) and gold?", "o": ["They always move in the same direction, with perfect positive correlation", "They typically move in inverse (negative) correlation", "There is no detectable relationship between them", "Gold's price is completely independent of every currency"], "e": "Since gold is priced in dollars, it typically moves in inverse correlation with the dollar index — a strengthening dollar typically keeps gold under pressure."},
  {"q": "What typically happens to the stock market when government bond yields suddenly rise?", "o": ["The stock market automatically and instantly drops to 0", "It is often pressured, because the risk-free yield becomes more attractive", "It has no effect on stocks whatsoever", "The stock market always rises by exactly as much as yields"], "e": "Rising bond yields make the risk-free alternative more attractive, which often puts pressure on riskier assets, including stocks."},
  {"q": "What does the \"risk-off\" market mood mean?", "o": ["Traders massively flee into risky assets (stocks, crypto)", "Capital flees into assets considered safe (dollar, gold, government bonds) out of fear", "Exchanges officially close for a day", "Interest rates automatically drop to zero"], "e": "In a risk-off mood, fear drives capital into assets considered safer (dollar, gold, government bonds), while risky assets weaken."},
  {"q": "Why should intermarket correlations be handled with caution?", "o": ["Because the law forbids using them in trading decisions", "Because correlation does not mean causation, and it can change over time or even reverse", "Because correlations are always exactly 100% and permanently constant", "Because only institutional traders can access this data"], "e": "Correlation is not causation, and it can change or even reverse over time — intermarket analysis is a supplementary tool, not a rule sufficient on its own."}
 ]},
"503": {"t": "Trading Macroeconomic Events", "s": "Fed decisions, NFP, CPI — how not to get burned by the news", "cards": [
  {"t": "The economic calendar", "b": "<p>Major market-moving events are known in advance: <strong style=\"color:#A855F7\">Fed rate decisions</strong>, <strong style=\"color:#A855F7\">NFP (Non-Farm Payrolls)</strong>, <strong style=\"color:#A855F7\">CPI (Consumer Price Index/inflation)</strong>. Their timing can be checked in advance in an economic calendar (e.g. ForexFactory, Investing.com) — professional traders always know when the next big event is coming.</p>"},
  {"t": "Volatility spike around the news", "b": "<p>Right around an important data release, the spread can widen, liquidity can temporarily disappear, and the price can move several percent in either direction within seconds, unpredictably. This is one of the most dangerous periods for beginner traders.</p>"},
  {"t": "\"Buy the rumor, sell the news\"", "b": "<p>It's a common phenomenon that the price already moves in advance of the news in response to EXPECTATIONS, and then at the actual release of the news — even if it's positive — it turns in the OPPOSITE direction, because the market had already 'priced in' the expected outcome. This phenomenon deceives many beginners.</p>"},
  {"t": "How do you protect yourself against news risk?", "b": "<p>Two realistic strategies: (1) <strong style=\"color:#A855F7\">staying out</strong> — simply not opening a position right before/during big news, or (2) if you're still in, using a <strong style=\"color:#A855F7\">significantly wider stop-loss</strong>, knowing that normal volatility can multiply at such times. For most beginner traders, the first option is the safer one.</p>"}],
 "qs": [
  {"q": "What is the NFP?", "o": ["The name of a technical chart pattern", "A monthly US labor-market statistic (Non-Farm Payrolls)", "An abbreviation for a brokerage firm", "A type of cryptocurrency"], "e": "The NFP (Non-Farm Payrolls) is a monthly US labor-market figure that often causes significant market volatility."},
  {"q": "What is typical of the market right around an important economic data release?", "o": ["Volatility and spread typically decrease, making trading safer", "Volatility can spike, the spread can widen, and the price can move unpredictably", "No change at all compared to normal trading conditions", "Exchanges automatically halt for every data release"], "e": "Around important data releases, volatility can suddenly spike, liquidity can temporarily worsen, and the price can move unpredictably, with large amplitude."},
  {"q": "What does the \"buy the rumor, sell the news\" phenomenon mean?", "o": ["That the market always moves exactly in the direction matching the news", "That the price reacts in advance to the expectation, then can turn in the opposite direction on the actual news, because it was already priced in", "That you should never trade based on news in any form", "That news only affects the crypto market"], "e": "The market often prices in the expected outcome in advance, so when the actual news arrives — even if positive — the price can turn in the opposite direction."},
  {"q": "What is the safest approach for a beginner trader during major news?", "o": ["Open as large a position as possible to take advantage of the volatility", "Rather stay out of the direct news window, or if already in, use a significantly wider stop", "Turn off the stop-loss so it doesn't close the trade too early", "Always trade in the opposite direction of what the news suggests"], "e": "For most beginner traders, staying out is the safest approach — or if still in, they must account for the spiking volatility with a correspondingly wider stop."}
 ]},
"508": {"t": "Market Microstructure and Liquidity Pools", "s": "How large players hide their true intentions in the order book", "cards": [
  {"t": "What is market microstructure?", "b": "<p><strong style=\"color:#A855F7\">Market microstructure</strong> examines EXACTLY how a price is formed at the level of buy/sell orders — not just HOW the price moves, but WHY it moves exactly the way the liquidity in the book allows.</p>"},
  {"t": "Iceberg orders", "b": "<p>An <strong style=\"color:#A855F7\">iceberg order</strong> displays a large buy/sell intention in the book as small, repeatedly refilling pieces — the goal is to keep the market from seeing the true, full size and moving against it before the entire order is executed.</p>"},
  {"t": "Liquidity pools on the chart", "b": "<p>Traders often place their stop-loss near round numbers or previous highs/lows — these densely clustered stop orders create <strong style=\"color:#A855F7\">liquidity pools</strong>, which larger players sometimes deliberately 'sweep' before turning in the real direction.</p>"},
  {"t": "What can a small trader do about this?", "b": "<p>You can't beat institutional order flow with an information edge, but you can know that obvious, 'everyone is in the same place' stop levels are more dangerous — so many experienced traders place their stop a bit FARTHER from the obvious level, where there is less of a 'crowd'.</p>"}],
 "qs": [
  {"q": "What is the purpose of an iceberg order?", "o": ["Faster execution of an order at a high fee", "Hiding the true, full size behind small, refilling pieces", "Automatically setting a stop-loss for every position", "Reducing the spread through market-maker activity"], "e": "An iceberg order hides the true, large size so the market doesn't move against it before execution."},
  {"q": "Why are 'obvious' stop-loss levels (e.g. round numbers) dangerous?", "o": ["Because trading is always commission-free there", "Because many traders' stops cluster there, which can make the level a target", "Because the exchange automatically halts trading there", "Because volatility is always lower there"], "e": "Densely clustered stop orders create a liquidity pool, which larger players sometimes deliberately 'sweep'."},
  {"q": "What does market microstructure analysis examine?", "o": ["Only the daily candles' closing price", "Exactly how a price forms at the level of orders", "The data in a company's financial statements", "The design of the trading platform's user interface"], "e": "Microstructure looks at EXACTLY how a price forms at the level of orders (order flow)."},
  {"q": "What does the lesson recommend to avoid obvious stop levels?", "o": ["Never use a stop-loss", "Place the stop a bit farther from the obvious, 'crowded' level", "Always use the tightest possible stop", "Automatically delete the stop when the market opens"], "e": "Placing the stop a bit farther from the obvious level reduces the chance that your stop specifically becomes the targeted liquidity."}
 ]},
"509": {"t": "Dark Pools and Institutional Trading", "s": "Deals happening outside the public book that still move the market", "cards": [
  {"t": "What is a dark pool?", "b": "<p>A <strong style=\"color:#A855F7\">dark pool</strong> is a private trading venue where large institutional players can trade WITH EACH OTHER, OUTSIDE the public order book — the goal is to keep a large-size deal from immediately and drastically moving the public price.</p>"},
  {"t": "Why does this exist?", "b": "<p>If a large fund wanted to sell a massive quantity at once in the public book, the price would collapse before the full quantity could be sold. A dark pool allows them to do this discreetly, with less market impact.</p>"},
  {"t": "What does this mean for a smaller trader?", "b": "<p>The volume seen in the public book does NOT show the full market activity — significant institutional movement can be happening 'invisibly'. This is one reason why a seemingly 'low-volume' move can actually have serious player activity behind it.</p>"},
  {"t": "A practical takeaway", "b": "<p>Since a smaller trader cannot see dark pool activity directly, the takeaway is NOT to try to decode it — but to treat 'visible' volume data with healthy skepticism, and not assume that the public book shows the full picture.</p>"}],
 "qs": [
  {"q": "What is the main purpose of a dark pool?", "o": ["Conducting illegal trading", "Conducting large institutional deals outside the public book, with less market impact", "Educating beginner traders", "Completely avoiding exchange fees"], "e": "A dark pool allows large deals to be conducted discreetly so they don't drastically move the public price."},
  {"q": "What does the public order book's volume data NOT show?", "o": ["The size of the spread", "The full market activity, including dark pool deals", "The candles' opening price", "The name of the trading platform"], "e": "Significant institutional activity happening in dark pools does not appear in the public book's volume data."},
  {"q": "Why do large funds avoid massive-size deals in the public book?", "o": ["Because the public book technically doesn't support large sizes", "Because it would immediately and drastically move the price against them", "Because the public book has a higher fee", "Because the public book is only accessible to retail traders"], "e": "A massive public deal would collapse the price before the full quantity could be sold."},
  {"q": "What is the right practical takeaway about dark pools for smaller traders?", "o": ["Try to exactly decode dark pool activity before every trade", "Treat it with healthy skepticism that visible volume shows the full picture", "Completely ignore volume data", "Only trade in dark pools"], "e": "The takeaway isn't to decode dark pools, but to accept that visible data isn't the full picture."}
 ]},
"510": {"t": "Seasonality and Calendar Effects", "s": "Recurring time-based patterns — and the trap they can set", "cards": [
  {"t": "What is seasonality?", "b": "<p><strong style=\"color:#A855F7\">Seasonality</strong> refers to recurring price patterns tied to a particular part of the year/month/week that have historically occurred more frequently than pure chance would justify (e.g. the 'January effect' in the stock market).</p>"},
  {"t": "Where do these patterns come from?", "b": "<p>Many seasonal effects have real, structural causes behind them — e.g. institutional portfolio rebalancing at year/quarter end, tax considerations, or recurring liquidity cycles. Others, however, are just STATISTICAL CHANCE, identified as a 'pattern' only in hindsight.</p>"},
  {"t": "The biggest trap: survivorship and data mining", "b": "<p>If you examine enough historical data from enough angles, you will EXACTLY find some kind of 'pattern' — that doesn't mean it's a real, causal relationship. This is <strong style=\"color:#A855F7\">data mining bias</strong>, and one of seasonality's biggest dangers.</p>"},
  {"t": "How to use it responsibly", "b": "<p>Seasonality is best treated at most as SUPPLEMENTARY context, never as a standalone trading signal — it can count as a 'bonus point' alongside a real technical/fundamental setup, but can never replace it.</p>"}],
 "qs": [
  {"q": "What is seasonality in trading?", "o": ["The day's temperature, which affects the price", "Recurring price patterns tied to particular calendar periods", "The name of a technical indicator", "The exchange's annual opening-hours schedule"], "e": "Seasonality refers to historically recurring patterns tied to a particular part of the year/month/week."},
  {"q": "What is the danger of 'data mining bias' in seasonality?", "o": ["That too much data needs to be stored to search for seasonality", "That in enough data from enough angles, you will always find some random 'pattern' that isn't a real relationship", "That seasonal data is expensive", "That seasonality only exists for crypto"], "e": "In enough data, you will always find a random pattern — that doesn't mean a real, reliable causal relationship stands behind it."},
  {"q": "How should seasonality be used responsibly?", "o": ["As a standalone, exclusive trading signal", "Only as supplementary context alongside a real setup, never on its own", "It should never be taken into account", "Only if an influencer confirms the seasonal pattern"], "e": "Seasonality can at most be supplementary context alongside a real technical/fundamental setup, not a standalone signal."},
  {"q": "What can stand behind real seasonal patterns?", "o": ["Only chance", "Structural causes, such as institutional portfolio rebalancing or tax considerations", "The exchange servers' maintenance cycle", "Lunar phases"], "e": "Some seasonal patterns have real structural causes, such as institutional portfolio rebalancing or taxes, although many other patterns are just statistical chance."}
 ]},
"511": {"t": "The Options Market's Impact on the Spot Price (Gamma Exposure)", "s": "How options-market hedging can leak into the underlying asset's price", "cards": [
  {"t": "What is gamma exposure (GEX)?", "b": "<p>When market makers sell a large quantity of options, they continuously <strong style=\"color:#A855F7\">delta-hedge</strong> their risk by BUYING/SELLING the underlying asset (e.g. a stock, BTC). <strong style=\"color:#A855F7\">Gamma exposure</strong> measures how FAST they have to adjust this hedge if the price moves.</p>"},
  {"t": "Positive vs. negative gamma environment", "b": "<p>In a positive gamma environment, market-maker hedging TYPICALLY reduces volatility (they sell as price rises, buy as it falls — this dampens the move). In a negative gamma environment, the OPPOSITE happens: their hedging AMPLIFIES the move (they buy as price rises, sell as it falls).</p>"},
  {"t": "The impact of options expiration days", "b": "<p>A large simultaneous expiration of options (e.g. monthly/quarterly expiration) can temporarily and significantly change market makers' hedging needs, which can explain why the market sometimes seems 'strangely pinned' to a price level near expiration, then suddenly moves AFTER expiration.</p>"},
  {"t": "What does this mean in practice?", "b": "<p>You don't need to precisely calculate GEX to benefit from this knowledge — it's enough to CONSCIOUSLY treat the period around large options-expiration days as a potentially higher- or lower-volatility, less predictable period.</p>"}],
 "qs": [
  {"q": "What does gamma exposure (GEX) measure?", "o": ["The trading platform's server capacity", "How fast market makers need to adjust their hedge if the price moves", "The size of options premiums", "The number of companies listed on the exchange"], "e": "GEX measures how sensitive market makers' hedging need is to price movement."},
  {"q": "What is typical of a negative gamma environment?", "o": ["Market-maker hedging reduces volatility", "Market-maker hedging amplifies (not reduces) the price move", "The options market completely shuts down", "The spot market and the options market separate from each other"], "e": "In a negative gamma environment, hedging activity amplifies, rather than reduces, the price move."},
  {"q": "Why can the market seem 'strangely pinned' near an options expiration?", "o": ["Because the exchange deliberately restricts movement", "Because the large quantity of expiring options changes market makers' hedging needs", "Because it's always a holiday at such times", "Because volume always drops to zero before expiration"], "e": "A large options expiration temporarily changes market makers' hedging needs, which can also affect the spot price."},
  {"q": "What is the practical takeaway about GEX for an average trader?", "o": ["They need to precisely calculate GEX before every trade", "It's enough to consciously handle the less predictable period around large options-expiration days", "GEX has no practical significance at all", "It's only relevant to options traders, never to spot traders"], "e": "Precise GEX calculation isn't necessary — it's enough for a trader to consciously handle the increased uncertainty around large options expirations."}
 ]},
"518": {"t": "DCA (Dollar-Cost Averaging): The Regular Investing Strategy", "s": "Why do many people invest the same amount every month, regardless of price?", "cards": [
  {"t": "What is DCA?", "b": "<p><strong style=\"color:#00D1FF\">Dollar-Cost Averaging (DCA)</strong> is a simple strategy: instead of investing the full amount at once, you invest the same amount at regular intervals (e.g. monthly) — regardless of whether the price is currently high or low.</p>"},
  {"t": "How does it lower the average price?", "b": "<p>With the same amount, you buy <strong style=\"color:#00D1FF\">more units at a low price</strong> and fewer units at a high price. In a volatile, sideways, or choppy market, this automatically brings down the average purchase price compared to investing the whole amount at once, at a random moment.</p>"},
  {"t": "When is DCA NOT better than a lump-sum investment?", "b": "<p>If the market RISES persistently and steadily (a strong, continuing bull market), then investing the full amount as early as possible statistically tends to perform better — because part of the DCA comes in later, already at a higher price. DCA's advantage lies not in the return, but in <strong style=\"color:#00D1FF\">reducing risk and regret</strong>.</p>"},
  {"t": "Why do many still choose DCA?", "b": "<p>DCA is psychologically easier to stick with: you don't have to try to &quot;time&quot; the market bottom, which is practically almost impossible. There's less chance of getting demoralized and exiting the market after a single badly timed, large investment — this is the main reason it's often recommended to long-term, regular savers.</p>"}],
 "qs": [
  {"q": "What is the essence of the DCA (Dollar-Cost Averaging) strategy?", "o": ["Always waiting for the market bottom, then investing everything at once", "Investing the same amount at regular intervals, regardless of price", "Only investing when the price is in an uptrend", "Concentrating all capital in a single asset instead of diversifying"], "e": "The essence of DCA is regular investing of the same amount, regardless of the current price — it doesn't try to time the market."},
  {"q": "In a volatile, choppy market, how does DCA typically affect the average purchase price?", "o": ["No effect — the average price always equals a lump-sum investment", "It can lower it, because it buys more units at a low price and fewer at a high price", "It always doubles the average price", "It only matters at the end of the investment, no effect in between"], "e": "With the same amount, you can buy more units at a low price and fewer at a high price — this can lower the average purchase price in a choppy market."},
  {"q": "In what market environment does a lump-sum investment typically outperform DCA?", "o": ["A persistently, steadily rising (strong bull) market", "A strongly sideways, directionless market", "Only when the market is closed", "Never — DCA is better under every market condition"], "e": "In a persistently rising market, investing the full amount as early as possible statistically tends to perform better, because part of the DCA is invested later, at a higher price."}
 ]},
"525": {"t": "Portfolio Rebalancing: Why Restore the Target Weights?", "s": "How does a simple, disciplined habit keep your risk level under control?", "cards": [
  {"t": "What is rebalancing?", "b": "<p><strong style=\"color:#00D1FF\">Rebalancing</strong> means periodically (e.g. annually) restoring your portfolio's asset weights to the originally set TARGET WEIGHTS — selling a bit of the well-performing assets and buying the worse-performing ones.</p>"},
  {"t": "Why does the weighting drift on its own?", "b": "<p>If a portfolio is never touched, the faster-growing assets (e.g. stocks, crypto) will over time take up an ever LARGER share than originally intended — the portfolio's risk profile shifts UNNOTICED toward the riskier direction.</p>"},
  {"t": "'Selling the winner, buying the loser' — why does this make sense?", "b": "<p>Rebalancing systematically forces you to take some profit off the RELATIVELY outperforming asset (sell high) and invest in the relatively underperforming one (buy low) — this is a built-in, emotion-free 'sell high, buy low' mechanism, as opposed to the instinctive urge to 'buy more of whatever is going well'.</p>"},
  {"t": "Does rebalancing have a cost?", "b": "<p>Rebalancing does not guarantee a higher return — if an asset PERSISTENTLY outperforms for years, regular rebalancing takes capital away from it early. Its primary benefit is not return maximization, but keeping the RISK LEVEL under control — see the Portfolio Simulator, where you can try out both scenarios.</p>"}],
 "qs": [
  {"q": "What happens to a portfolio that is never rebalanced?", "o": ["The weights always automatically stay equal", "The faster-growing assets take up an ever larger share, shifting the risk profile", "The portfolio's value always drops to zero", "No effect at all, the weights don't matter"], "e": "Without rebalancing, the share of faster-growing (typically riskier) assets grows over time, and the portfolio's risk profile shifts unnoticed."},
  {"q": "Why can rebalancing be called a built-in 'sell high, buy low' mechanism?", "o": ["Because it always sells off the worst asset entirely", "Because it takes from the relatively outperforming asset (sells) and invests in the relatively underperforming one (buys)", "Because no actual buying or selling ever happens", "Because it guarantees the highest possible return"], "e": "Restoring target weights systematically takes from the relatively better-performing asset and invests in the relatively worse-performing one — an emotion-free, disciplined mechanism."},
  {"q": "What is rebalancing's primary benefit?", "o": ["It guarantees a higher return in every case", "Keeping the risk level under control, not maximizing returns", "Completely avoiding transaction fees", "Eliminating all portfolio risk"], "e": "Rebalancing's main goal is maintaining the targeted risk level — it does not guarantee a higher return, especially when an asset persistently outperforms."}
 ]},
"530": {"t": "Technical vs. Fundamental Analysis: Two Different Approaches", "s": "Are you looking at the price movement, or the real value behind the company?", "cards": [
  {"t": "What is technical analysis?", "b": "<p><strong style=\"color:#00D1FF\">Technical analysis</strong> (what the app's lessons have focused on so far) examines only the past patterns of price AND volume — trendlines, indicators, candlestick patterns — starting from the assumption that all relevant information is already reflected in the price.</p>"},
  {"t": "What is fundamental analysis?", "b": "<p><strong style=\"color:#00D1FF\">Fundamental analysis</strong> tries to estimate a company's (or asset's) TRUE UNDERLYING VALUE — based on financial statements, revenue, profit, industry position — and examines whether the current price counts as under- or overvalued relative to that.</p>"},
  {"t": "Who is each one for?", "b": "<p>A day trader or scalper, who thinks in minutes to hours, typically relies on TECHNICAL analysis, because fundamentals don't change within minutes. A long-term investor, who holds a position for months to years, pays much more attention to the FUNDAMENTALS.</p>"},
  {"t": "Why is it worth knowing both?", "b": "<p>Many professional traders COMBINE the two: they use fundamentals to filter out WHICH asset is worth watching (e.g. strong, growing companies), then use technical analysis to decide WHEN it's worth entering/exiting a good position.</p>"}],
 "qs": [
  {"q": "What does technical analysis focus on?", "o": ["The company's financial statements and revenue", "The past patterns of price and volume", "Exclusively the company management's biography", "Cryptocurrencies' reputation on social media"], "e": "Technical analysis examines the past data and patterns of price and volume, starting from the assumption that all relevant information is already reflected in the price."},
  {"q": "What does fundamental analysis try to answer?", "o": ["How likely a candlestick pattern is to continue", "Whether the company's/asset's current price is under- or overvalued relative to its true, underlying value", "Which indicator gives an earlier signal", "The size of the daily trading fee"], "e": "Fundamental analysis estimates a company's true, underlying value based on financial data, and compares it with the market price."},
  {"q": "Why do day traders typically rely more on technical analysis?", "o": ["Because fundamentals change drastically every day", "Because they think in minutes to hours, and fundamentals don't change meaningfully in such a short timeframe", "Because fundamental analysis is illegal in day trading", "Because technical analysis always gives a more accurate forecast"], "e": "A day trader operates on a short timeframe (minutes to hours), where fundamentals (revenue, profit, etc.) don't change meaningfully — so they focus on the patterns of price and volume, i.e. technical analysis."}
 ]},
"531": {"t": "The P/E Ratio: The Best-Known Fundamental Metric", "s": "What does it mean when a stock is called 'expensive' or 'cheap' relative to its earnings?", "cards": [
  {"t": "What is the P/E ratio?", "b": "<p>The <strong style=\"color:#00D1FF\">P/E ratio (Price-to-Earnings)</strong> shows how many times the stock's price is of the annual earnings per share (EPS). Formula: P/E = Share price ÷ EPS.</p>"},
  {"t": "What does a high or low P/E mean?", "b": "<p>A HIGH P/E can signal that the market expects strong future growth from the company (or that the stock is overpriced). A LOW P/E can signal cheaper pricing — but it can also be low because the market sees weak prospects for the company. The P/E on its own is NEVER enough for a decision.</p>"},
  {"t": "Why compare within an industry?", "b": "<p>The P/E ratio is only worth comparing between companies within the SAME industry — a fast-growing tech company can naturally 'deserve' a higher P/E than a stable, slow-growing utility company, without being overpriced because of it.</p>"},
  {"t": "What is EPS?", "b": "<p><strong style=\"color:#00D1FF\">EPS (Earnings Per Share)</strong> divides the company's total net profit by the number of shares outstanding — this is the P/E ratio's denominator, and an important profitability metric on its own as well.</p>"}],
 "qs": [
  {"q": "How is the P/E ratio calculated?", "o": ["Share price multiplied by EPS", "Share price divided by the annual earnings per share (EPS)", "The company's total market capitalization divided by volume", "The dividend divided by the share price"], "e": "The P/E (Price-to-Earnings) ratio divides the share price by the annual earnings per share (EPS)."},
  {"q": "Why isn't the P/E ratio enough on its own for an investment decision?", "o": ["Because the P/E ratio can never be calculated precisely", "Because a high or low value on its own doesn't say whether it stems from growth expectations or over-/undervaluation — context (e.g. industry comparison) is needed", "Because the P/E ratio only applies to cryptocurrencies", "Because the P/E ratio is always exactly the same for every company"], "e": "Interpreting the P/E ratio requires context — a high P/E can signal strong growth expectations or overvaluation, which can only be judged by comparing with similar companies and other metrics."},
  {"q": "What does EPS (Earnings Per Share) mean?", "o": ["The company's total market capitalization", "The company's net profit divided by the number of shares outstanding", "The daily trading volume in dollars", "The total amount of the company's debt"], "e": "EPS divides the company's net profit by the number of shares outstanding — it's a standalone profitability metric and also the P/E ratio's denominator."}
 ]},
"532": {"t": "Dividends: Income from Holding a Stock", "s": "How can a stock generate money for you without you selling it?", "cards": [
  {"t": "What is a dividend?", "b": "<p>A <strong style=\"color:#00D1FF\">dividend</strong> is a portion of a company's profit that it REGULARLY (typically quarterly) pays out to its shareholders, a fixed amount per share — this is one source of income from holding a stock, alongside price appreciation.</p>"},
  {"t": "What is dividend yield?", "b": "<p><strong style=\"color:#00D1FF\">Dividend yield</strong> compares the annual dividend amount with the current share price (dividend yield = annual dividend ÷ share price × 100%) — this shows what percentage 'interest' you get each year on the amount invested, purely from the dividend, independent of price changes.</p>"},
  {"t": "Why doesn't every company pay a dividend?", "b": "<p>Many fast-growing companies (typically tech companies) do NOT pay a dividend — instead they REINVEST the profit into growth (new products, expansion). With these companies, an investor can only expect returns from price appreciation, not from a dividend.</p>"},
  {"t": "The trap of a 'too high' dividend yield", "b": "<p>A SUSPICIOUSLY high dividend yield is often not good news — it's typically high because the stock price has FALLEN (the yield's numerator is unchanged, the denominator decreased), and the market may already be expecting the company to cut or eliminate the dividend in the future. Dividend yield should NEVER be treated on its own as 'free money'.</p>"}],
 "qs": [
  {"q": "What is a dividend?", "o": ["The daily fluctuation of a stock's price", "A portion of a company's profit, regularly paid out to its shareholders", "A trading fee charged by the broker", "The opening price of exchange trading"], "e": "A dividend is a portion of a company's profit that it regularly pays out to its shareholders, a fixed amount per share."},
  {"q": "How is dividend yield calculated?", "o": ["Annual dividend multiplied by the number of shares", "Annual dividend divided by the current share price, expressed as a percentage", "The company's total market capitalization divided by the price", "The product of the P/E ratio and EPS"], "e": "Dividend yield compares the annual dividend with the current share price (dividend ÷ price × 100%), showing the percentage return from the dividend."},
  {"q": "Why can a suspiciously high dividend yield be a dangerous sign?", "o": ["Because a high dividend yield is always illegal", "Because it's often high because the share price fell, and the market may expect a dividend cut/elimination", "Because companies with a high dividend yield never actually pay the dividend", "There is no such danger — a high dividend yield is always clearly good news"], "e": "A suspiciously high dividend yield often arises because the price fell (the yield's denominator decreased) — this can point to the market expecting a future dividend cut or elimination."}
 ]},
"536": {"t": "Central Bank Rate Decisions: How They Affect the Markets", "s": "Why does a simple interest-rate announcement move the entire market?", "cards": [
  {"t": "What is the Policy Rate?", "b": "The benchmark interest rate set by a central bank (e.g. the US Fed, the European Central Bank), at which banks borrow short-term from each other. This is the 'price of money' for the entire economy — it influences mortgages, corporate loans, and indirectly the pricing of every asset class."},
  {"t": "Rate hikes: why does the stock market fall because of this?", "b": "Higher rates → more expensive credit for companies → lower present value of future profits (since future cash flows are discounted at a higher rate) → stocks' theoretical 'fair value' falls. In addition, bond yields also rise, making them more competitive against riskier stocks."},
  {"t": "Rate cuts: the 'easy money' effect", "b": "Lower rates → cheaper credit → growth expectations improve → capital turns toward riskier assets (stocks, crypto), because the safe (bond) yield is low. This is one reason why the crypto market and tech stocks are especially sensitive to rate policy."},
  {"t": "The market reacts to the surprise, not the decision", "b": "Markets price in expected decisions in advance. If the central bank does exactly what everyone expected, the reaction can be minimal. Big moves come when the decision or its accompanying commentary DIFFERS from expectations — that's why the 'surprise factor' matters more than the raw number."}],
 "qs": [
  {"q": "What typically happens to stocks as a result of a rate hike?", "o": ["They always rise immediately and significantly", "They typically come under pressure, because the present value of future profits falls and bonds become more competitive", "No effect is observed at all", "Only cryptocurrencies react to it"], "e": "Higher rates make credit more expensive and raise the discount rate, which lowers the present value of future profits — this typically pressures stock prices, especially in growth sectors."},
  {"q": "Why can there be a small market reaction to a rate decision if it matches expectations?", "o": ["Because the central bank hides the decision", "Because markets have already priced in the expected outcomes in advance, and the lack of a 'surprise' carries less new information", "Because rate decisions never have a market impact", "Because only the bond market reacts to rate decisions"], "e": "The market has already built the expectations into prices — only an outcome (or surprising commentary) that differs from expectations causes significant, new price reactions."},
  {"q": "Why are tech stocks and crypto sensitive to rate policy?", "o": ["Because they aren't even traded on rate-decision days", "Because they are riskier, future-profit-focused assets, whose pricing is more strongly influenced by the discount rate and 'easy money' capital flows", "Because these assets pay a fixed interest rate", "Because the central bank directly regulates their price"], "e": "These assets are largely priced on future (often distant) profits, so they're more strongly sensitive to changes in the discount rate and shifts in risk appetite."}
 ]},
"537": {"t": "Yield Curve Inversion: The Recession Warning Sign", "s": "Why is a simple curve flip called one of the most reliable recession indicators?", "cards": [
  {"t": "What is the Yield Curve?", "b": "The yield curve plots the yields of government bonds with different maturities (e.g. 3-month, 2-year, 10-year) on a chart. Normally, longer-maturity bonds offer higher yields — this compensates for the risk and uncertainty of committing for a longer time."},
  {"t": "What is Inversion?", "b": "When short-term bond yields EXCEED long-term yields (e.g. the 2-year yield is higher than the 10-year), the curve 'inverts'. This signals that the market is pricing in higher interest rate/risk in the short term than in the long term — which contradicts normal expectations."},
  {"t": "Why does it signal a recession?", "b": "Inversion typically reflects the market expecting the central bank to cut rates in the near future (in response to a slowing economy) — so long-term yields fall below short-term ones. Historically (in the US, over several decades), US yield curve inversion has preceded almost every recession."},
  {"t": "Important warning: the timing is uncertain", "b": "Between the inversion and the actual start of a recession, 6–24 months can pass — this is NOT an immediate trading signal. For a trader, it's more of a macro context: a warning to be cautious and review exposure to cyclical sectors, not an immediate 'sell everything' command."}],
 "qs": [
  {"q": "What does yield curve inversion mean?", "o": ["Long-term bond yields are higher than short-term ones", "Short-term bond yields are higher than long-term ones", "All bond yields are equally zero", "The bond market has completely shut down"], "e": "In an inversion, the short-term yield exceeds the long-term yield — a reversal of the normal state (long > short)."},
  {"q": "Why is yield curve inversion considered a recession signal?", "o": ["Because the government decrees it so", "Because historically it preceded most recessions, reflecting the market's expectation of rate cuts", "Because it's just a random correlation with no explanation", "Because inversion immediately lowers GDP"], "e": "Inversion signals that the market expects a slowing economy and future rate cuts — this pattern has historically reliably preceded recessions."},
  {"q": "Why shouldn't inversion be treated as an immediate trading signal?", "o": ["Because inversion has never been an accurate indicator", "Because there can be a delay of as much as 6–24 months between the signal and the actual start of a recession", "Because the yield curve changes several times a day", "Because the theory only applies to US bonds"], "e": "Historical data shows a significant, uncertain time lag between the appearance of inversion and the actual onset of a recession, making it more of a long-term context than an immediate trigger."}
 ]},
"540": {"t": "Taxation of Capital Gains in Hungary: Personal Income Tax (SZJA) Basics", "s": "How much tax is owed on stock-market profit without a long-term investment account (TBSZ)?", "cards": [
  {"t": "The standard rule: 15% personal income tax", "b": "In Hungary, individuals' stock-market gains (shares, ETFs, forex, crypto) are by default subject to a 15% personal income tax (SZJA). Important: this applies to the PROFIT, not the full withdrawn amount — so recovering your invested capital is not taxed, only the profit portion."},
  {"t": "Netting gains and losses", "b": "Within a tax year (and under certain conditions, in the following two years) gains and losses from stock-market transactions can be netted against each other — if you gain on one position and lose on another, tax is owed only on the NET result. This is an important incentive for keeping precise records and retaining documentation."},
  {"t": "TBSZ as a tax-exemption tool (reminder)", "b": "The long-term investment account (TBSZ) provides 0% personal income tax on gains made within it if held for 5 years (see the TBSZ calculator and the related lesson in the Hungarian Market tab) — that's why many Hungarian investors keep their long-term positions in a TBSZ, while short-term/speculative trading stays on a normal, taxable account."},
  {"t": "Important: this is not tax advice", "b": "Tax regulations can change, and individual circumstances (e.g. special rules for crypto trading, using a foreign broker, social contribution tax in certain cases) may be treated differently. Always consult an accountant or tax advisor about your own specific situation — this lesson only provides general information."}],
 "qs": [
  {"q": "What is the default personal income tax rate on stock-market capital gains in Hungary, without a TBSZ?", "o": ["0%", "15%", "25%", "33%"], "e": "Individuals' stock-market capital gains are by default subject to a 15% personal income tax without a TBSZ."},
  {"q": "Does the personal income tax apply to the full withdrawn amount or just the profit?", "o": ["The full withdrawn amount, including the invested capital", "Only the realized profit — recovering the invested capital is tax-free", "Only dividends, never capital gains", "A fixed fee in every case, regardless of the result"], "e": "The tax applies to realized profit — there is no tax liability when recovering invested capital, only on the profit."},
  {"q": "What does holding a TBSZ for 5 years provide, in terms of capital gains tax?", "o": ["A doubled tax rate", "0% personal income tax on the gains made in the account", "An automatic tax refund on other accounts too", "Tax exemption only for dividends, never for capital gains"], "e": "The TBSZ is one of the most important Hungarian tax-optimization tools: after a 5-year holding period, capital gains (and dividends) earned in the account are subject to 0% personal income tax."}
 ]},
"542": {"t": "Pairs Trading: A Market-Neutral Strategy", "s": "How can you make a profit without guessing the market's direction?", "cards": [
  {"t": "The basic idea of pairs trading", "b": "Pairs trading watches two historically co-moving (strongly correlated) assets (e.g. two similar-industry stocks). When the price difference (spread) between them moves significantly away from its usual level, the trader simultaneously goes LONG the relatively cheaper, and SHORT the relatively more expensive asset — betting that the spread will revert to its mean."},
  {"t": "Why 'market-neutral'?", "b": "Since there's a long and a short position at the same time, if the ENTIRE market falls or rises, the two positions largely cancel each other out — the profit/loss primarily depends on the two assets' movement RELATIVE TO EACH OTHER, not the market's general direction. This makes it attractive in an uncertain or sideways market environment."},
  {"t": "The importance of cointegration", "b": "It's not enough that two assets' price movements correlated in the past — when selecting a pair, it's important that the relationship is also fundamentally justified (e.g. same industry, similar business model). A purely random, statistical correlation ('spurious correlation') can break down at any time, and the spread may never revert — this is the strategy's biggest risk."},
  {"t": "Practical challenges", "b": "Pairs trading requires double the transaction fees, wider spread costs, and more complex position sizing (the two legs need to be dollar-neutral or beta-neutral). The short position also carries a borrowing fee and theoretically unlimited loss — which is why this is more of an advanced than a beginner strategy."}],
 "qs": [
  {"q": "What is the fundamental operation of pairs trading?", "o": ["Simultaneously buying two completely independent assets", "Going long the relatively cheaper, and short the relatively more expensive, historically correlated asset at the same time", "Buying double the size of the same asset", "Only opening short positions on any asset"], "e": "The strategy's essence is that the trader bets on the spread between the two correlated assets reverting to its mean, not on either asset's absolute direction."},
  {"q": "Why is pairs trading called 'market-neutral'?", "o": ["Because you can never lose with it", "Because the simultaneous long and short position largely cancels out the effect of the overall market's direction, and the spread's movement matters primarily", "Because it can only be done with government bonds", "Because it requires no capital to execute"], "e": "The long and short position together largely neutralizes the effect of the market's general direction — profit/loss depends primarily on the two assets' movement relative to each other."},
  {"q": "What is one of pairs trading's biggest risks?", "o": ["That you have to wait too long for profit", "That the correlation between the two assets was only chance, and the spread never reverts to its mean", "That the strategy only works with crypto", "That it requires no analysis at all"], "e": "If the relationship between the two assets isn't fundamentally justified but just a chance statistical correlation, the spread can diverge without ever reverting — this can cause the strategy to fail."}
 ]},
"543": {"t": "Overfitting and Walk-Forward Testing: The Backtesting Trap", "s": "Why does a seemingly perfect backtested strategy often perform catastrophically live?", "cards": [
  {"t": "What is overfitting?", "b": "Overfitting happens when a strategy's parameters (e.g. EMA period, RSI level) are tuned on a given historical dataset until it fits that specific data almost perfectly — including its random noise, not just the genuine, repeating patterns. The result is a strategy that has memorized the PAST, rather than learning the market's real logic."},
  {"t": "The warning sign: too many parameters", "b": "The more freely adjustable parameters a strategy has (entry level, exit level, filters, timing), the easier it is to accidentally find a 'perfect' combination on a given historical stretch — simply because of the large number of possibilities, not because the strategy hides a genuine edge. Simpler strategies with fewer parameters are typically more robust."},
  {"t": "What is walk-forward testing?", "b": "Walk-forward testing guards against overfitting by splitting the historical data into consecutive time segments: the strategy is 'optimized' on one segment (in-sample), then tested on the NEXT, not-yet-seen segment (out-of-sample) — rolling this process forward across the entire dataset. We only trust the strategy if it also performs consistently on the out-of-sample segments."},
  {"t": "The basic rule: held-back data (out-of-sample)", "b": "The simplest defense: NEVER optimize the strategy on all available data. Always hold back a portion (e.g. the last 20-30%) that you never looked at while developing the strategy, and test on it only at the VERY END, once — if it performs well there too, that's far stronger evidence than the in-sample result."}],
 "qs": [
  {"q": "What is the essence of overfitting in backtesting?", "o": ["The strategy uses too little data", "Parameters are tuned on a dataset until they fit even the random noise, not just the genuine pattern", "The strategy runs too fast on a computer", "Backtest results are always too pessimistic"], "e": "In overfitting, the strategy fits the historical data's random quirks (noise), not a genuine, repeating market pattern — so it doesn't generalize well to new data."},
  {"q": "What is walk-forward testing used for?", "o": ["Measuring the strategy's speed", "Checking whether the strategy also performs consistently on 'unseen' data segments not used for optimization", "Calculating transaction fees", "Automatically setting position size"], "e": "Walk-forward testing splits the data into consecutive in-sample (optimized) and out-of-sample (not-yet-seen) segments, to give a more realistic picture of the strategy's future performance."},
  {"q": "Why are strategies with fewer parameters typically more robust?", "o": ["Because they always give a higher return", "Because there are fewer degrees of freedom for accidental fitting, so the overfitting risk is smaller", "Because they require no testing at all", "Because only these are allowed by most brokers"], "e": "The more parameters a strategy has, the more room there is for random, data-specific fitting — simpler rules with fewer parameters are less prone to this."}
 ]},
"545": {"t": "Gold and Safe-Haven Assets in Times of Crisis", "s": "Why have investors turned to gold during market turmoil for millennia?", "cards": [
  {"t": "What makes an asset a 'Safe Haven'?", "b": "A safe-haven asset typically shows low or negative correlation with risky assets (stocks, crypto) during market stress — when investors panic and flee from risk ('risk-off' mood), demand for (and often the price of) these assets rises, while risky assets fall."},
  {"t": "Gold's Millennia-Old Role", "b": "Because of its limited supply, physical durability, and independence from governments/the banking system, gold is traditionally the best-known safe haven. It typically performs well in a high-inflation environment (since it can't be 'printed' like fiat money) and during geopolitical uncertainty."},
  {"t": "An Important Nuance: Not Perfect, and Doesn't Always Work", "b": "Gold can also be volatile in the short term, pays no interest/dividend (the 'opportunity cost' is a real factor in a rising-rate environment), and doesn't react the same way in every crisis — for example, in a sudden, extreme liquidity crisis (like March 2020), gold's price can also temporarily fall, because investors convert everything to cash."},
  {"t": "Other 'Safe Haven' Candidates and Their Limits", "b": "US Treasury bonds and certain strong currencies (e.g. the Swiss franc, Japanese yen) are also traditional havens. In the crypto community, Bitcoin is sometimes called 'digital gold', but historically (so far) it has behaved more like a high-risk, risk-on asset during crises, not as a classic haven — an important, often misunderstood distinction."}],
 "qs": [
  {"q": "What generally characterizes a safe-haven asset?", "o": ["High correlation with risky assets during market stress", "Low or negative correlation with risky assets during market stress, when investors are fleeing risk", "A guaranteed, fixed annual return under all circumstances", "It can only be an asset issued by a government"], "e": "Safe-haven assets typically perform well (or at least stably) exactly when risky assets fall — meaning their correlation with them is low or negative during crises."},
  {"q": "Why isn't gold a perfect safe haven in every situation?", "o": ["Because gold always loses value during a crisis", "Because in an extreme liquidity crisis (e.g. March 2020) it also temporarily fell, as everything was converted to cash, and it pays no interest/dividend", "Because gold can only be used as jewelry", "Because gold's price is fixed and regulated, it never changes"], "e": "In extreme, sudden liquidity shocks, even gold fell temporarily, because market participants wanted to convert everything to cash — on top of that, gold generates no ongoing income (interest/dividend), which is a real opportunity cost."},
  {"q": "How has Bitcoin historically behaved in most market crises, contrary to the 'digital gold' label?", "o": ["It always behaved exactly like physical gold", "It behaved more like a high-risk, 'risk-on' asset, not a classic safe haven", "It never showed volatility during a crisis", "It was completely independent of the stock market at all times"], "e": "Although Bitcoin is often called 'digital gold' because of its limited supply, in reality it has so far moved more like a risk-on asset alongside the stock market during crises, not as a classic safe-haven asset."}
 ]},
"546": {"t": "Leveraged and Inverse ETFs: The Hidden Trap (Volatility Decay)", "s": "Why can you lose money on a 2x leveraged ETF even if the underlying index eventually returns to where it started?", "cards": [
  {"t": "What is a Leveraged ETF?", "b": "A 2x or 3x leveraged ETF aims to deliver twice/three times the underlying index's DAILY return (e.g. if the S&P 500 goes +1% today, the 3x ETF targets roughly +3%). Important: this multiplication happens DAILY (reset every day, 'daily reset'), not over the entire holding period."},
  {"t": "What is an Inverse (Short) ETF?", "b": "An inverse ETF targets the opposite of the underlying index's DAILY return (e.g. if the index goes -1%, the inverse ETF targets roughly +1%) — without the investor actually having to open a short position or margin account. Leveraged inverse versions also exist (e.g. -2x, -3x)."},
  {"t": "The Volatility Decay Trap", "b": "Because the multiplication happens DAILY, relative to that day's closing value, in a sideways but volatile market the leveraged ETF's VALUE CAN DECLINE OVER THE LONG TERM, even if the underlying index eventually returns to where it started. Numeric example: if the index goes -10% one day, then +11.11% the next (back to the original level), a 2x ETF moves -20% then +22.22% — which is NOT 0%, but a net loss (0.98 × 1.0 × 0.8 × 1.2222 ≈ 0.978, i.e. about -2.2%)."},
  {"t": "Who Is It For (And Who Isn't It For)?", "b": "Issuers designed leveraged/inverse ETFs specifically for INTRADAY, short-term speculation and tactical hedging — NOT for long-term 'buy and hold' investing. The more volatile the market and the longer the holding period, the bigger the distorting effect of volatility decay. For long-term exposure, a plain (1x) index ETF is typically a much more suitable tool."}],
 "qs": [
  {"q": "What does a leveraged ETF's multiplier (e.g. 2x, 3x) apply to?", "o": ["The entire holding period's return, no matter how long you hold it", "The underlying index's DAILY return, reset every day", "Only the dividend, not the price", "Any period the investor chooses"], "e": "Leveraged ETFs target the underlying index's DAILY (not long-term) return with a multiplier, and reset every day — this is what causes the long-term distortion."},
  {"q": "What is the 'volatility decay' phenomenon?", "o": ["A leveraged ETF always delivers exactly the underlying index's multiple over the long term too", "In a sideways, volatile market, due to the daily reset, a leveraged ETF's value can decline over the long term, even if the index returns to its starting level", "The ETF's management fee increases every year", "It only happens with inverse ETFs, never with leveraged ones"], "e": "Because of the daily reset, in a back-and-forth market (that nets to 0%), a leveraged ETF can mathematically lose value — this is called volatility decay."},
  {"q": "What investment horizon did issuers primarily design leveraged/inverse ETFs for?", "o": ["Decades-long, retirement-savings-purpose holding", "Intraday, short-term speculation or tactical hedging", "Only for cryptocurrency portfolios", "Permanent positions that are never sold"], "e": "Issuers designed these instruments specifically for short-term, typically intraday use — holding them long-term can significantly worsen performance relative to the underlying index's actual return due to volatility decay."}
 ]},
"547": {"t": "Corporate Actions: Stock Splits and Buybacks", "s": "What does it mean when a company 'splits' its shares, or buys back its own stock?", "cards": [
  {"t": "What is a Stock Split?", "b": "A stock split (e.g. a '4-for-1' split) quadruples the number of shares outstanding while dividing the price by four — the company's TOTAL market value (market cap) theoretically stays unchanged. The goal is typically to make the per-share price lower and more 'affordable' for smaller investors, for psychological/liquidity reasons."},
  {"t": "Important: A Split Alone Doesn't Create Real Value", "b": "If a $400 stock becomes a $100 stock after a 4-for-1 split (with 4x the share count), your portfolio's total value does NOT change. The market sometimes still reacts positively to the announcement — this prices in the IMPLICIT message behind the split (management's confidence in future growth), rather than the mechanical split itself."},
  {"t": "What is a Buyback?", "b": "In a buyback, a company uses its own money to repurchase and 'retire' a portion of its own shares from the market. This reduces the number of shares outstanding, which — with unchanged total profit — increases earnings per share (EPS), potentially making the P/E ratio and the share price more attractive."},
  {"t": "The Two Faces of a Buyback", "b": "On one hand, it can signal that management believes the stock is undervalued and is confident about the future (a positive sign). On the other hand, critics argue that some companies use buybacks to 'artificially' inflate EPS and metrics tied to executive bonuses, instead of investing the capital in R&D or new projects — so a buyback alone is never a sufficient investment reason; the context (why, at what price, versus what alternative) matters."}],
 "qs": [
  {"q": "What theoretically happens to a company's total market value (market cap) during a stock split?", "o": ["It quadruples", "It drops to a quarter", "It stays unchanged — only the share count rises and the price falls proportionally", "It automatically drops to zero"], "e": "A stock split merely splits the shares into more, lower-priced units — the company's total market value theoretically doesn't change because of it."},
  {"q": "What is a buyback's direct accounting effect, with unchanged total profit?", "o": ["It decreases earnings per share (EPS)", "It increases earnings per share (EPS), since fewer shares share the same profit", "It has no effect on any metric", "It automatically doubles the dividend"], "e": "Since the number of shares outstanding decreases, the same total profit is divided among fewer shares — this raises EPS, even with unchanged profit."},
  {"q": "Why isn't a buyback announcement alone a sufficient positive investment signal?", "o": ["Because a buyback always lowers the share price", "Because some companies use it to artificially improve metrics instead of real investment, so the context (why, at what price) matters", "Because buybacks are legally banned in most countries", "Because a buyback automatically signals bankruptcy"], "e": "A buyback alone can be a positive sign (confidence in the future) or a negative one (a worse use of capital than R&D or investment), so it's worth examining the circumstances of the decision, not just the fact of the announcement."}
 ]},
"548": {"t": "Insider Trading: What Counts as a Violation?", "s": "Where is the line between 'good research' and illegal insider trading?", "cards": [
  {"t": "What Counts as Inside Information?", "b": "Inside (non-public, 'material non-public') information is data that has not yet been made public, and that would LIKELY significantly affect the stock's price if the market learned of it — e.g. an unannounced acquisition, an unexpected quarterly loss, or the outcome of a drug-approval decision that a company employee learns of before the public does."},
  {"t": "Why Does the Law Ban It in Almost Every Developed Market?", "b": "The purpose of banning insider trading is to maintain a level playing field — if some people regularly traded on illegally obtained information, other (outside) investors would be structurally disadvantaged, undermining trust in the markets and the basic functioning of capital markets."},
  {"t": "It's Not Just About Company Executives", "b": "The rule doesn't only apply to company executives (classic 'insiders'), but to anyone who obtains inside information and uses it or passes it on ('tipping') — e.g. a lawyer, accountant, bank employee, or even a friend whom an insider tells the news to over dinner, if that person trades on it."},
  {"t": "What's the Difference Between Legal 'Deep Research' and Insider Trading?", "b": "Legal market analysis is built on PUBLICLY available information, however thoroughly it is gathered and processed (financial reports, industry trends, experts' PUBLIC opinions). The violation begins when someone trades while in possession of specific, price-moving information from a CLOSED, confidential source not yet available to the public."}],
 "qs": [
  {"q": "What is the essence of inside (material non-public) information?", "o": ["Any publicly available financial data", "Non-public information that would likely significantly affect the price if the market learned of it", "Only a company's official press releases", "Signals generated by technical analysis"], "e": "Inside information is something not yet public that, if it were, would likely significantly move the price — trading while possessing it is considered a violation."},
  {"q": "Who can the ban on insider trading apply to?", "o": ["Exclusively the company's CEO", "Anyone who obtains inside information and uses or passes it on, not just classic company executives", "Only institutional investors, never individuals", "No one — the rule is only a moral recommendation, not law"], "e": "The rule extends to anyone who obtains inside information (e.g. advisors, employees, or people an insider tells), not just a company's executives."},
  {"q": "What is the main difference between legal, in-depth research and insider trading?", "o": ["There is no difference, both are violations", "Legal research is built on publicly available information, while insider trading is based on using closed, non-public, specific information", "Legal research can only mean technical analysis", "The difference depends solely on the size of the trade"], "e": "Legal analysis — however thorough — is built on publicly accessible data; the violation begins where someone trades on specific information obtained from a confidential, non-public source."}
 ]},
"549": {"t": "Mergers and Acquisitions (M&A): Impact on the Share Price", "s": "Why does a stock's price suddenly jump when an acquisition offer is announced?", "cards": [
  {"t": "The Basic Pattern: Acquisition Premium", "b": "When a company (the 'acquirer') announces it wants to buy another publicly traded company (the 'target'), it typically offers a price HIGHER than the market price (an acquisition premium, e.g. +20-40%) to convince shareholders. The target's stock typically jumps immediately and sharply after the announcement — close to (but rarely exactly at) the offer price."},
  {"t": "Why Doesn't It Jump EXACTLY to the Offer Price?", "b": "The market price stays below the offer price by a small gap (the so-called 'merger arbitrage spread'), because the deal's closing is not guaranteed — regulatory approval (antitrust authorities), shareholder votes, or financing problems can cause the deal to fall through. The less certain the deal's success, the bigger this gap."},
  {"t": "Cash Deal vs. Stock-for-Stock Deal", "b": "In an 'all-cash' acquisition, the target's shareholders receive a fixed dollar amount per share. In a 'stock-for-stock' deal, they receive the acquirer's OWN shares in exchange, at a set ratio — in this case, the target's price also becomes dependent on the acquirer's price, making the pricing more complex."},
  {"t": "What Happens to the Acquirer's Stock?", "b": "Interestingly, the ACQUIRER's stock often FALLS after the announcement — the market may worry that it's overpaying for the target, that integration will be risky, or that the deal's financing (new debt, new share issuance) will dilute existing shareholders. 'Who wins, who loses' is therefore NOT automatic — it's always worth checking both sides' reaction."}],
 "qs": [
  {"q": "What typically happens to the TARGET company's share price when an acquisition offer is announced?", "o": ["It typically falls immediately and sharply", "It typically jumps, close to (but rarely exactly at) the offered acquisition price", "It never changes", "It automatically drops to zero"], "e": "An acquisition offer typically offers a premium over the market price, so the target's share price jumps after the announcement, near the offer price (but not always exactly matching it)."},
  {"q": "Why does the market price typically stay below the offered acquisition price by a small gap?", "o": ["Because exchange rules forbid otherwise", "Because the deal's closing isn't guaranteed (regulatory approval, vote, financing), and the market prices in this uncertainty", "Because investors never trust acquisitions", "Because the offer price is always wrong"], "e": "The remaining gap ('merger arbitrage spread') reflects the risk that the deal might not go through for some reason (lack of approval, financing problems)."},
  {"q": "Why can the ACQUIRER company's share price fall after the announcement?", "o": ["Because the acquirer's stock never reacts to the news", "Because the market may worry about overpaying, integration risk, or the dilutive effect of financing", "Because the law forbids the acquirer's stock from rising", "Because the acquirer's stock automatically ceases to exist"], "e": "The market is often skeptical about the price, the integration's success, or the financing method (e.g. the dilutive effect of a new share issuance), which can pressure the acquirer's price even as the target's price rises."}
 ]},
"550": {"t": "Algorithmic Trading Basics: When the Machine Decides", "s": "What's the difference between manual, systematic, and fully automated trading?", "cards": [
  {"t": "What is Algorithmic Trading?", "b": "Algorithmic trading automatically generates and/or executes orders based on predetermined, mathematical rules — without human intervention (or with minimal human oversight). The EMA-crossover, RSI, Bollinger, and MACD strategies tried in the app's Backtester are all ALGORITHMS, which could in principle also be automated."},
  {"t": "The Three Levels: Manual, Systematic, Automated", "b": "1) Manual: the trader decides freely on every single trade, even based on technical/fundamental analysis. 2) Systematic (but manually executed): the trader follows fixed rules (e.g. 'I always buy when condition X is met'), but presses the button themselves. 3) Fully automated: a program watches the market and INDEPENDENTLY executes orders according to the rules, with no human approval."},
  {"t": "The Advantages of Algorithmic Trading", "b": "No emotional bias (the program isn't afraid and isn't greedy), consistent, tireless execution (even 0-24h, e.g. for crypto), and the ability to react to signals within seconds that a human would miss. On top of that, the rules can be EXACTLY backtested — there's no subjective 'I remember it this way...' bias when evaluating results."},
  {"t": "The Risks: Not a Magic Button", "b": "An algorithm is only as good as the logic behind it and the quality of its backtesting — a poorly tested, overfitted algorithm can lose money just as easily, and even faster and at larger scale, as a bad manual strategy. On top of that, technical risks (internet outage, API error, broker-side issue) can also arise, which a manual trader would immediately notice, but an unsupervised algorithm would not."}],
 "qs": [
  {"q": "What distinguishes 'systematic, but manually executed' trading from fully automated trading?", "o": ["There is no difference between them", "In systematic trading, the trader follows fixed rules but executes the order themselves; in automated trading, a program does this with no human approval", "Systematic trading is always faster", "Automated trading never uses technical indicators"], "e": "A systematic trader decides according to fixed rules but submits the order themselves — an automated system also takes over this step, executing the trade independently."},
  {"q": "What is one of algorithmic trading's most important advantages?", "o": ["It's always guaranteed to be profitable", "No emotional bias, consistent execution, and the rules can be precisely backtested", "It requires no prior testing at all", "It eliminates the possibility of technical errors"], "e": "The algorithm isn't afraid and isn't greedy, consistently executes the rules, and since the logic is precisely defined, it can be backtested objectively, without subjective bias."},
  {"q": "Why isn't algorithmic trading a 'magic button'?", "o": ["Because it's illegal in most countries", "Because a poorly tested, overfitted algorithm can lose money just as easily, even faster, plus technical risks (connection outage, API error) can also arise", "Because algorithms never generate trading signals", "Because it only applies to cryptocurrencies"], "e": "An algorithm is only as good as the thoroughly tested logic behind it — a flawed or overfitted strategy loses money even when automated, and unsupervised technical errors can also go unnoticed."}
 ]},
"551": {"t": "ESG and Sustainable Investing: What Does It Mean in Practice?", "s": "How do investors try to reconcile financial returns with environmental and social impact?", "cards": [
  {"t": "What Does ESG Stand For?", "b": "ESG stands for Environmental, Social, and Governance — criteria investors use to evaluate how well a company's operations meet certain sustainability and ethical expectations, alongside traditional financial metrics (profit, revenue)."},
  {"t": "How Do People Invest Based on ESG?", "b": "Several approaches exist: 'negative screening' (excluding certain industries, e.g. tobacco, weapons manufacturing, from the portfolio), 'positive screening' (preferring companies with the best ESG scores within an industry), and 'impact investing' (investment specifically aimed at measurable social/environmental impact, e.g. financing renewable energy projects)."},
  {"t": "The Risk of 'Greenwashing'", "b": "Because ESG rating is not uniformly regulated, and different rating firms (e.g. MSCI, Sustainalytics) use different methodologies, the same company can receive significantly different ESG scores depending on the source. Some companies ('greenwashing') may present themselves as better than their actual practices for marketing purposes — so it's worth investors examining the methodology too, not just the final score."},
  {"t": "Does ESG Investing Produce Lower Returns?", "b": "This is debated, with mixed empirical research results: some studies find that ESG screening doesn't cause a significant return sacrifice (and even showed outperformance in some sectors/periods), while others argue that the narrowed investable universe limits diversification and can lead to a return sacrifice over the long run. As with many investment questions, there's no single, indisputable answer here — the actual result strongly depends on the period, the sector, and the specific screening methodology."}],
 "qs": [
  {"q": "What does the abbreviation ESG stand for?", "o": ["Earnings, Sales, Growth (financial metrics)", "Environmental, Social, Governance", "Equity, Stock, Gold (asset classes)", "Exchange, Settlement, Guarantee"], "e": "ESG stands for Environmental, Social, and Governance considerations, which investors factor in alongside traditional financial metrics."},
  {"q": "What is the risk of 'greenwashing' in ESG investing?", "o": ["That every ESG fund is automatically unprofitable", "That a company can present itself as more sustainable than its actual practice, while ESG rating methodology is also not uniformly regulated", "That ESG investing is legally banned in most countries", "That greenwashing only occurs in the cryptocurrency market"], "e": "Since there's no uniform ESG regulation and rating firms' methodologies differ, companies can present their sustainability practices as better than reality for marketing purposes — this is called greenwashing."},
  {"q": "What do studies on ESG investment returns show?", "o": ["Clearly and indisputably higher returns in every case", "Mixed, debated results — in some cases there's no significant return sacrifice, in others the narrowed universe can limit diversification", "That ESG investing always and exclusively produces losses", "That returns depend solely on company size, not ESG factors"], "e": "Research results are mixed and strongly depend on the period, sector, and methodology — there is no single, indisputable answer as to whether ESG screening improves or worsens returns."}
 ]}
});
